#!/usr/bin/env node
// Generates each coding agent's files from the one source: AGENTS.md and agents/*.md.
//
//   node adapters/sync.mjs           write the generated files        (npm run agents:sync)
//   node adapters/sync.mjs --check   fail if any differs or is stale  (npm run agents:check)
//
// Formats, read from each vendor's documentation on 2026-11-17:
//   Claude Code  CLAUDE.md with an `@AGENTS.md` import; sub-agents in .claude/agents/<name>.md (front matter: name,
//                description, tools).
//   Codex        reads AGENTS.md itself; sub-agents in .codex/agents/<name>.toml (name, description,
//                developer_instructions).
//   Gemini CLI   .gemini/settings.json -> context.fileName lists AGENTS.md; sub-agents in .gemini/agents/<name>.md.
//   Qwen Code    .qwen/settings.json -> context.fileName, plus QWEN.md as a full copy because the docs don't confirm
//                AGENTS.md as a value; sub-agents in .qwen/agents/<name>.md.
// AKCK_ROOT sets the project folder (default: this repository). No dependencies.
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(process.env.AKCK_ROOT || path.join(path.dirname(fileURLToPath(import.meta.url)), '..'));
const NOTICE = 'GENERATED by adapters/sync.mjs. Do not edit: change AGENTS.md or agents/*.md, then run `npm run agents:sync`.';
const CAPABILITIES = ['read', 'write', 'shell', 'web-search', 'web-fetch', 'browser'];
const CLAUDE_TOOLS = {
  read: ['Read', 'Glob', 'Grep'],
  write: ['Write', 'Edit'],
  shell: ['Bash'],
  'web-search': ['WebSearch'],
  'web-fetch': ['WebFetch'],
  browser: [],
};

const read = (rel) => readFileSync(path.join(ROOT, rel), 'utf8').replace(/\r\n/g, '\n');

/** Front matter in the small subset the agent files use: `key: text` and `key: [a, b]`. */
export function parseAgent(text, file) {
  const m = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(text);
  if (!m) throw new Error(`${file}: must start with front matter between --- lines`);
  const meta = {};
  for (const line of m[1].split('\n').filter((l) => l.trim())) {
    const kv = /^([a-z]+):\s*(.*)$/.exec(line);
    if (!kv) throw new Error(`${file}: can't read the front matter line "${line}"`);
    const list = /^\[(.*)\]$/.exec(kv[2]);
    meta[kv[1]] = list ? list[1].split(',').map((s) => s.trim()).filter(Boolean) : kv[2].trim();
  }
  for (const key of ['name', 'description', 'capabilities']) if (!meta[key]?.length) throw new Error(`${file}: front matter needs "${key}"`);
  if (!/^[a-z0-9-]+$/.test(meta.name)) throw new Error(`${file}: name must be lowercase letters, digits and hyphens`);
  if (`${meta.name}.md` !== path.basename(file)) throw new Error(`${file}: name "${meta.name}" must match the file name`);
  for (const c of meta.capabilities) if (!CAPABILITIES.includes(c)) throw new Error(`${file}: unknown capability "${c}"`);
  return { meta, body: m[2].trim() };
}

const yamlText = (s) => JSON.stringify(s);
const tomlText = (s) => `"""\n${s.replace(/\\/g, '\\\\').replace(/"""/g, '""\\"')}\n"""`;
const capabilityNote = (a) => `Capabilities this agent needs: ${a.meta.capabilities.join(', ')}. Use only your tools that provide them.`;

function markdownAgent(a, extra = []) {
  return ['---', `name: ${a.meta.name}`, `description: ${yamlText(a.meta.description)}`, ...extra, '---', '', `<!-- ${NOTICE} -->`, '', capabilityNote(a), '', a.body, ''].join('\n');
}

export function generate() {
  const out = new Map();
  const rules = read('AGENTS.md');
  const agents = readdirSync(path.join(ROOT, 'agents')).filter((f) => f.endsWith('.md')).sort()
    .map((f) => parseAgent(read(`agents/${f}`), `agents/${f}`));

  out.set('CLAUDE.md', `@AGENTS.md\n\n<!-- ${NOTICE} -->\n`);
  out.set('QWEN.md', `<!-- ${NOTICE} -->\n\n${rules}`);
  const settings = JSON.stringify({ context: { fileName: ['AGENTS.md'] } }, null, 2) + '\n';
  out.set('.gemini/settings.json', settings);
  out.set('.qwen/settings.json', JSON.stringify({ context: { fileName: ['AGENTS.md', 'QWEN.md'] } }, null, 2) + '\n');

  for (const a of agents) {
    const tools = [...new Set(a.meta.capabilities.flatMap((c) => CLAUDE_TOOLS[c]))];
    out.set(`.claude/agents/${a.meta.name}.md`, markdownAgent(a, [`tools: ${tools.join(', ')}`]));
    out.set(`.gemini/agents/${a.meta.name}.md`, markdownAgent(a));
    out.set(`.qwen/agents/${a.meta.name}.md`, markdownAgent(a));
    out.set(`.codex/agents/${a.meta.name}.toml`, [
      `# ${NOTICE}`,
      `name = ${JSON.stringify(a.meta.name)}`,
      `description = ${JSON.stringify(a.meta.description)}`,
      `developer_instructions = ${tomlText(`${capabilityNote(a)}\n\n${a.body}`)}`,
      '',
    ].join('\n'));
  }
  return out;
}

/** Generated agent files on disk that no source agent produces any more. */
function strays(expected) {
  const found = [];
  for (const dir of ['.claude/agents', '.gemini/agents', '.qwen/agents', '.codex/agents']) {
    const full = path.join(ROOT, dir);
    if (!existsSync(full)) continue;
    for (const f of readdirSync(full)) if (!expected.has(`${dir}/${f}`)) found.push(`${dir}/${f}`);
  }
  return found;
}

function main() {
  const check = process.argv.includes('--check');
  let files;
  try {
    files = generate();
  } catch (e) {
    console.error(`agents: FAIL\n  ${e.message}`);
    process.exit(1);
  }
  const problems = [];
  for (const [rel, want] of files) {
    const full = path.join(ROOT, rel);
    const have = existsSync(full) ? readFileSync(full, 'utf8').replace(/\r\n/g, '\n') : null;
    if (have === want) continue;
    if (check) problems.push(`${rel}: ${have === null ? 'is missing' : 'differs from its source'}`);
    else {
      mkdirSync(path.dirname(full), { recursive: true });
      writeFileSync(full, want);
    }
  }
  for (const s of strays(files)) problems.push(`${s}: has no source in agents/ (delete it)`);
  if (problems.length) {
    console.error(`agents:${check ? 'check' : 'sync'}: FAIL\n${problems.map((p) => `  ${p}`).join('\n')}${check ? '\n  Run `npm run agents:sync`; never edit a generated file.' : ''}`);
    process.exit(1);
  }
  console.log(`agents:${check ? 'check' : 'sync'}: PASS (${files.size} generated files)`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
